<script>
import aboutPopup from '@/components/aboutPopup.vue';
import progressPopup from "@/components/progressPopup.vue";
export default {
  components: {
    aboutPopup,
    progressPopup
  },
  data(){
    return{
      clickable: true,
      showProg: false
    }
  },
  methods: {
    doStart(){
      if (!this.clickable){
        return false;
      }
      this.clickable = false;
      document.getElementById('potion0').style.opacity = 0;
      setTimeout(() => {this.$router.replace('/story')}, 1000)

    },
    openAbout(){
      this.$refs.popup.doOpen();
    },
    openProg(){
      this.$refs.prog.doOpen();
    },
    openQuit(){
      var r=confirm("Are you sure you want to quit?");
      if (r){
        window.history.back();
      }
    },
    doOpenSound(){
      this.$emit('openSound', false)
    }
  },
  created() {
    let spottedList = localStorage.getItem('spottedList')
    if (spottedList.length > 0) {
      try {
        let spottedListArr = JSON.parse(spottedList)
        this.showProg = spottedListArr.length > 0
      } catch (err) {
        this.showProg = false;
      }
    }
  }
}
</script>

<template>
  <div class="clickpotion">
    <div class="potion_outer">
      <div class="potion_inner" id="potion0">
        <button class="startbtn" @click="doStart">Play!</button>
        <span @click="openProg" v-if="showProg">Statistic</span>
        <span @click="doOpenSound">Sound settings</span>
        <span @click="openAbout">About</span>
        <span @click="openQuit">Quit</span>
      </div>
    </div>
    <about-popup ref="popup"></about-popup>
    <progress-popup ref="prog"></progress-popup>
  </div>
</template>

<style scoped lang="scss">
@media (orientation: portrait){
  .potion_outer {
    width: 100% !important;
    height: auto !important;
  }
  .potion_inner{
    button{
      font-size: 6vw !important;
    }
    span{
      font-size: 4vw !important;
      margin-top: 12px;
    }
  }
  .hint_text{
    font-size: 4vw;
  }
}
.clickpotion {
  width: 100%;
  height: 100vh;
  background-color: #ab47bc;
  overflow: hidden;
  user-select: none;
  display: flex;
  align-items: center;
  justify-content: center;

  .potion_outer {
    aspect-ratio: 1259/1575;
    width: auto;
    height: 100%;
    margin: 0 auto;
    background-color: black;
    position: relative;
    .potion_inner {
      width: auto;
      height: 100%;
      position: relative;
      background-color: black;
      transition: opacity 1000ms;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      *{
        font-family: "Cherry Bomb One", sans-serif !important;
      }
      button{
        width: 60%;
        height: 10%;
        min-height: 48px;
        border-radius: 100vh;
        background-color: #a1529b;
        border: none;
        font-size: 3vh;
        color: white;
        box-shadow: 0 0 8px white;
        cursor: pointer;
        transition: 300ms;
        &:hover{
          box-shadow: 0 0 24px white;
        }
      }
      span{
        color: white;
        font-size: 2vh;
        margin-top: 12px;
        cursor: pointer;
      }
    }
  }
}
</style>
